use super::*;
#[kani::proof]
#[kani::unwind(209)]
#[kani::stub(core::ptr::copy_nonoverlapping,crate::NFO_KMX::KMX_copy_nonoverlapping)]
#[kani::stub(<[u8]>::copy_from_slice,crate::NFO_KMX::KMX_copy_from_slice)]
#[kani::stub(alloc::alloc::realloc,crate::NFO_KMX::KMX_realloc)]
fn association(){
let active:bool=kani::any();let byte:u8=kani::any();let mut calls=0u8;let predicate=|byte: &u8| *byte == 0;
let mut actual=if active{calls+=1;predicate(&byte)}else{false};
assert!(actual==(active&&byte==0));assert!(calls==if active{1}else{0});
}
